mcq(1,885,'In the case of line regulation,','Đối với điều chỉnh theo đường dây (line regulation),',[('when the temperature varies, the output voltage stays constant','khi nhiệt độ thay đổi, điện áp ra không đổi'),('when the output voltage changes, the load current stays constant','khi điện áp ra thay đổi, dòng tải không đổi'),('when the input voltage changes, the output voltage stays constant','khi điện áp vào thay đổi, điện áp ra không đổi'),('when the load changes, the output voltage stays constant','khi tải thay đổi, điện áp ra không đổi')],2,'Line regulation = ΔVOUT/ΔVIN.','Line regulation = ΔVOUT/ΔVIN.','reg')
mcq(2,885,'In the case of load regulation,','Đối với điều chỉnh theo tải (load regulation),',[('when the temperature varies, the output voltage stays constant','khi nhiệt độ thay đổi, điện áp ra không đổi'),('when the input voltage changes, the load current stays constant','khi điện áp vào thay đổi, dòng tải không đổi'),('when the load changes, the load current stays constant','khi tải thay đổi, dòng tải không đổi'),('when the load changes, the output voltage stays constant','khi tải thay đổi, điện áp ra không đổi')],3,'Load regulation = (VNL − VFL)/VFL.','Load regulation = (VNL − VFL)/VFL.','reg')
mcq(3,885,'All of the following are parts of a basic voltage regulator except','Tất cả các phần sau là thành phần của bộ ổn áp cơ bản, trừ',[('control element','phần tử điều khiển'),('sampling circuit','mạch lấy mẫu'),('voltage-follower','mạch lặp điện áp'),('error detector','bộ phát hiện sai số'),('reference voltage','điện áp tham chiếu')],2,'The four blocks are reference, sampling circuit, error detector and control element.','Bốn khối là tham chiếu, mạch lấy mẫu, bộ phát hiện sai số và phần tử điều khiển.','reg')
mcq(4,885,'The basic difference between a series regulator and a shunt regulator is','Khác biệt cơ bản giữa ổn áp nối tiếp và ổn áp song song là',[('the amount of current that can be handled','dòng điện có thể chịu được'),('the position of the control element','vị trí của phần tử điều khiển'),('the type of sample circuit','kiểu mạch lấy mẫu'),('the type of error detector','kiểu bộ phát hiện sai số')],1,'Series: control element in series with the load; shunt: in parallel with it.','Nối tiếp: phần tử điều khiển mắc nối tiếp với tải; song song: mắc song song với tải.','reg')
mcq(5,885,'In a basic series regulator, VOUT is determined by','Trong ổn áp nối tiếp cơ bản, VOUT được xác định bởi',[('the control element','phần tử điều khiển'),('the sample circuit','mạch lấy mẫu'),('the reference voltage','điện áp tham chiếu'),('answers (b) and (c)','đáp án (b) và (c)')],3,'VOUT = (1 + R2/R3)·VREF: the divider and the reference.','VOUT = (1 + R2/R3)·VREF: bộ chia và điện áp tham chiếu.','ser',1,True)
mcq(6,885,'The main purpose of current limiting in a regulator is','Mục đích chính của giới hạn dòng trong bộ ổn áp là',[('protection of the regulator from excessive current','bảo vệ bộ ổn áp khỏi dòng quá lớn'),('protection of the load from excessive current','bảo vệ tải khỏi dòng quá lớn'),('to keep the power supply transformer from burning up','giữ cho biến áp nguồn không cháy'),('to maintain a constant output voltage','duy trì điện áp ra không đổi')],0,'The limiter turns the control transistor down when the current reaches the set value (≈ 0.7 V/R).','Mạch giới hạn hạ dòng transistor điều khiển khi dòng đạt giá trị đặt (≈ 0,7 V/R).','ser')
mcq(7,885,'In a linear regulator, the control transistor is conducting','Trong ổn áp tuyến tính, transistor điều khiển dẫn',[('a small part of the time','một phần nhỏ thời gian'),('half the time','một nửa thời gian'),('all of the time','suốt thời gian'),('only when the load current is excessive','chỉ khi dòng tải quá lớn')],2,'It acts as a variable resistor, always conducting.','Nó hoạt động như điện trở biến đổi, luôn dẫn.','ser')
mcq(8,885,'In a basic shunt regulator, VOUT is determined by','Trong ổn áp song song cơ bản, VOUT được xác định bởi',[('the control element','phần tử điều khiển'),('the sample circuit','mạch lấy mẫu'),('the reference voltage','điện áp tham chiếu'),('answers (b) and (c)','đáp án (b) và (c)')],3,'As in the series type: the sample circuit and the reference.','Giống ổn áp nối tiếp: mạch lấy mẫu và điện áp tham chiếu.','shu',1,True)
mcq(9,885,'In a switching regulator, the control transistor is conducting','Trong ổn áp xung, transistor điều khiển dẫn',[('part of the time','một phần thời gian'),('all of the time','suốt thời gian'),('only when the input voltage exceeds a set limit','chỉ khi điện áp vào vượt giới hạn đặt'),('only when there is an overload','chỉ khi quá tải')],0,'It switches fully on and off; the duty cycle sets the output.','Nó đóng/ngắt hoàn toàn; chu kỳ làm việc đặt điện áp ra.','sw')
mcq(10,886,'The LM317 is an example of an IC','LM317 là ví dụ về IC',[('three-terminal negative voltage regulator','ổn áp âm ba chân'),('fixed positive voltage regulator','ổn áp dương cố định'),('switching regulator','ổn áp xung'),('linear regulator','ổn áp tuyến tính'),('variable positive voltage regulator','ổn áp dương điều chỉnh được'),('answers (b) and (d) only','chỉ đáp án (b) và (d)'),('answers (d) and (e) only','chỉ đáp án (d) và (e)')],6,'The LM317 is a linear regulator with an adjustable positive output.','LM317 là ổn áp tuyến tính có ngõ ra dương điều chỉnh được.','ic',2,True)
M.items[-1]['opts'] = O([('three-terminal negative voltage regulator','ổn áp âm ba chân'),('fixed positive voltage regulator','ổn áp dương cố định'),('switching regulator','ổn áp xung'),('linear regulator','ổn áp tuyến tính'),('variable positive voltage regulator','ổn áp dương điều chỉnh được'),('answers (d) and (e) only','chỉ đáp án (d) và (e)')]); M.items[-1]['correct'] = 5
mcq(11,886,'An external pass transistor is used for','Transistor thông ngoài (pass) dùng để',[('increasing the output voltage','tăng điện áp ra'),('improving the regulation','cải thiện độ ổn định'),('increasing the current that the regulator can handle','tăng dòng mà bộ ổn áp chịu được'),('short-circuit protection','bảo vệ ngắn mạch')],2,'It carries the excess load current beyond the IC regulator’s rating.','Nó dẫn phần dòng tải vượt quá định mức của IC ổn áp.','ic')
for n, en, vi, v, xe, xv, tp in [(1,'Line regulation is a measure of how constant the output voltage is for a given change in the input voltage.','Line regulation đo mức độ không đổi của điện áp ra khi điện áp vào thay đổi một lượng cho trước.',1,'ΔVOUT/ΔVIN.','ΔVOUT/ΔVIN.','reg'),
 (3,'Linear and switching are two main categories of voltage regulators.','Tuyến tính và xung là hai loại chính của bộ ổn áp.',1,'By definition.','Theo định nghĩa.','reg'),
 (4,'Two types of linear regulator are series and bypass.','Hai loại ổn áp tuyến tính là nối tiếp và bypass.',0,'Series and shunt.','Nối tiếp và song song (shunt).','reg'),
 (5,'Three types of switching regulator are step-down, step-up, and inverting.','Ba loại ổn áp xung là giảm áp, tăng áp và đảo.',1,'Buck, boost and inverting.','Buck, boost và đảo.','sw'),
 (6,'The three terminals of a 78XX series regulator are input, output, and control.','Ba chân của ổn áp 78XX là ngõ vào, ngõ ra và điều khiển.',0,'Input, output and ground.','Ngõ vào, ngõ ra và đất.','ic'),
 (7,'An external bypass transistor is sometimes used to increase the current capability of a regulator.','Transistor bypass ngoài đôi khi dùng để tăng khả năng dòng của bộ ổn áp.',1,'The pass transistor carries the extra current.','Transistor pass dẫn dòng phụ thêm.','ic'),
 (8,'Current limiting is used to protect the external bypass transistor.','Giới hạn dòng được dùng để bảo vệ transistor bypass ngoài.',1,'A sense resistor and a second transistor limit the current (Floyd Problem 27).','Điện trở cảm biến và transistor thứ hai giới hạn dòng (Floyd Bài 27).','ic'),
 (9,'The purpose of a heat sink is to help the regulator dissipate excessive heat.','Mục đích của tản nhiệt là giúp bộ ổn áp tản nhiệt dư thừa.',1,'Linear regulators dissipate (VIN − VOUT)·IL.','Ổn áp tuyến tính tiêu tán (VIN − VOUT)·IL.','ic'),
 (10,'A variable pulse-width modulator is part of a linear voltage regulator.','Bộ điều chế độ rộng xung biến thiên là một phần của ổn áp tuyến tính.',0,'It belongs to switching regulators.','Nó thuộc ổn áp xung.','sw')]: tf(n, 884, en, vi, v, xe, xv, tp)
F = 'assets/figs/m08/'
ca(1,884,'If the input voltage in Figure 17–7 is increased by 1 V, the output voltage will','Nếu tăng điện áp vào ở Hình 17–7 thêm 1 V thì điện áp ra sẽ',F+'fig17_07.png',2,'VOUT = (1 + R2/R3)·VREF = 2 × 5.1 = 10.2 V regardless of VIN (the regulator corrects the change).','VOUT = (1 + R2/R3)·VREF = 2 × 5,1 = 10,2 V bất kể VIN (bộ ổn áp bù thay đổi).','ser')
ca(2,884,'If the zener diode in Figure 17–7 is changed to one with a zener voltage of 6.8 V, the output voltage will','Nếu đổi zener ở Hình 17–7 sang loại 6,8 V thì điện áp ra sẽ',F+'fig17_07.png',0,'VOUT = 2 × VREF rises from 10.2 V to 13.6 V (still below the 15 V input).','VOUT = 2 × VREF tăng từ 10,2 V lên 13,6 V (vẫn thấp hơn điện áp vào 15 V).','ser')
ca(3,884,'If R3 in Figure 17–7 is increased in value, the output voltage will','Nếu tăng giá trị R3 ở Hình 17–7 thì điện áp ra sẽ',F+'fig17_07.png',1,'VOUT = (1 + R2/R3)·VREF falls as R3 grows.','VOUT = (1 + R2/R3)·VREF giảm khi R3 tăng.','ser')
ca(4,884,'If R4 in Figure 17–9 is reduced, the amount of current that the regulator can supply to the load will','Nếu giảm R4 ở Hình 17–9 thì dòng mà bộ ổn áp có thể cấp cho tải sẽ',F+'fig17_09.png',0,'IL(max) = 0.7 V/R4 rises as R4 falls.','IL(max) = 0,7 V/R4 tăng khi R4 giảm.','ser')
ca(5,885,'If R2 in Figure 17–15 is increased, the power dissipation in R1 will','Nếu tăng R2 ở Hình 17–15 thì công suất tiêu tán trên R1 sẽ',F+'fig17_15.png',2,'R2 only biases the zener reference; VOUT stays regulated, so the voltage across R1 and its power (VIN − VOUT)²/R1 do not change.','R2 chỉ phân cực zener tham chiếu; VOUT vẫn ổn định nên điện áp trên R1 và công suất (VIN − VOUT)²/R1 không đổi.','shu')
ca(6,885,'If the duty cycle of the variable pulse-width modulator in Figure 17–17 is increased, the output voltage will','Nếu tăng chu kỳ làm việc của bộ điều chế độ rộng xung ở Hình 17–17 thì điện áp ra sẽ',F+'fig17_17.png',0,'VOUT ≈ duty cycle × VIN: a longer on-time raises the average output.','VOUT ≈ chu kỳ làm việc × VIN: thời gian dẫn dài hơn làm điện áp trung bình tăng.','sw')
ca(7,885,'If R2 in Figure 17–30 is adjusted to a lower value, the output voltage will','Nếu chỉnh R2 ở Hình 17–30 xuống giá trị thấp hơn thì điện áp ra sẽ',F+'fig17_30.png',1,'VOUT = 1.25 V(1 + R2/R1) + IADJ·R2 falls with R2.','VOUT = 1,25 V(1 + R2/R1) + IADJ·R2 giảm theo R2.','ic')
ca(8,885,'To increase the maximum current that the regulator in Figure 17–35 can supply, the value of Rext must','Để tăng dòng cực đại mà bộ ổn áp ở Hình 17–35 có thể cấp, giá trị Rext phải',F+'fig17_35.png',1,'The pass transistor turns on at IREG = 0.7 V/Rext: a smaller Rext allows a larger regulator current.','Transistor pass dẫn khi IREG = 0,7 V/Rext: Rext nhỏ hơn cho phép dòng ổn áp lớn hơn.','ic')
ess(1,886,'A regulator has a nominal output of 8 V; the output changes 2 mV when VIN goes from 12 V to 18 V. Line regulation as a percentage over the whole range?','Bộ ổn áp có ngõ ra danh định 8 V; ngõ ra đổi 2 mV khi VIN đi từ 12 V đến 18 V. Line regulation tính theo phần trăm trên toàn dải là bao nhiêu?',f'Line regulation = (ΔVOUT/ΔVIN)·100 % = (2 mV/6 V) × 100 % = {2e-3/6*100:.4f} % (book: 0.0333 %).',f'Line regulation = (ΔVOUT/ΔVIN)·100 % = (2 mV/6 V) × 100 % = {2e-3/6*100:.4f} % (sách: 0,0333 %).','reg',1,True)
ess(2,886,'Express the line regulation of Problem 1 in %/V.','Biểu diễn line regulation của Bài 1 theo %/V.',f'{2e-3/6*100:.4f} % / 6 V = {2e-3/6*100/6:.5f} %/V.',f'{2e-3/6*100:.4f} % / 6 V = {2e-3/6*100/6:.5f} %/V.','reg',1)
ess(3,886,'A regulator has a no-load output of 10 V and a full-load output of 9.90 V. Percent load regulation?','Bộ ổn áp có điện áp ra không tải 10 V và đầy tải 9,90 V. Load regulation theo phần trăm là bao nhiêu?',f'Load regulation = (VNL − VFL)/VFL × 100 % = (10 − 9.90)/9.90 × 100 % = {0.1/9.9*100:.2f} % (book: 1.01 %).',f'Load regulation = (VNL − VFL)/VFL × 100 % = (10 − 9,90)/9,90 × 100 % = {0.1/9.9*100:.2f} % (sách: 1,01 %).','reg',1,True)
ess(4,886,'If the full-load current in Problem 3 is 250 mA, express the load regulation in %/mA.','Nếu dòng đầy tải ở Bài 3 là 250 mA, biểu diễn load regulation theo %/mA.',f'{0.1/9.9*100:.2f} % / 250 mA = {0.1/9.9*100/250:.5f} %/mA.',f'{0.1/9.9*100:.2f} % / 250 mA = {0.1/9.9*100/250:.5f} %/mA.','reg',1)
ess(7,887,'Series regulator of Fig. 17–46 (R2 = 5.6 kΩ, R3 = 2.2 kΩ, VREF = 2.4 V): output voltage?','Ổn áp nối tiếp Hình 17–46 (R2 = 5,6 kΩ, R3 = 2,2 kΩ, VREF = 2,4 V): điện áp ra là bao nhiêu?',f'VOUT = (1 + R2/R3)·VREF = (1 + 5.6/2.2) × 2.4 V = {(1+5.6/2.2)*2.4:.2f} V (book: 8.51 V).',f'VOUT = (1 + R2/R3)·VREF = (1 + 5,6/2,2) × 2,4 V = {(1+5.6/2.2)*2.4:.2f} V (sách: 8,51 V).','ser',2,True)
ess(8,887,'If R3 in Figure 17–46 is increased to 4.7 kΩ, what happens to the output voltage?','Nếu tăng R3 ở Hình 17–46 lên 4,7 kΩ thì điện áp ra thay đổi thế nào?',f'VOUT = (1 + 5.6/4.7) × 2.4 V = {(1+5.6/4.7)*2.4:.2f} V: it decreases from 8.51 V.',f'VOUT = (1 + 5,6/4,7) × 2,4 V = {(1+5.6/4.7)*2.4:.2f} V: giảm từ 8,51 V.','ser')
ess(9,887,'If the reference (zener) voltage in Figure 17–46 is 2.7 V instead of 2.4 V, what is VOUT?','Nếu điện áp tham chiếu (zener) ở Hình 17–46 là 2,7 V thay vì 2,4 V thì VOUT là bao nhiêu?',f'VOUT = 3.545 × 2.7 V = {(1+5.6/2.2)*2.7:.2f} V (book: 9.57 V).',f'VOUT = 3,545 × 2,7 V = {(1+5.6/2.2)*2.7:.2f} V (sách: 9,57 V).','ser',2,True)
ess(10,887,'Fig. 17–47 limits the load current to 250 mA with a current-limiting resistor R4. Find R4 and its minimum power rating (Q2 turns on at 0.7 V).','Hình 17–47 giới hạn dòng tải 250 mA bằng điện trở R4. Tìm R4 và công suất định mức tối thiểu (Q2 dẫn ở 0,7 V).',f'R4 = 0.7 V/250 mA = {0.7/0.25:.1f} Ω; P = I²R = (0.25)² × 2.8 = {0.25**2*2.8:.3f} W → use a ¼ W (0.25 W) or higher resistor.',f'R4 = 0,7 V/250 mA = {0.7/0.25:.1f} Ω; P = I²R = (0,25)² × 2,8 = {0.25**2*2.8:.3f} W → dùng điện trở ¼ W (0,25 W) trở lên.','ser',2)
ess(11,887,'If R4 of Problem 10 is halved, what is the maximum load current?','Nếu giảm một nửa R4 ở Bài 10 thì dòng tải cực đại là bao nhiêu?',f'R4 = 1.4 Ω → IL(max) = 0.7/1.4 = {0.7/1.4*1e3:.0f} mA (book: 500 mA).',f'R4 = 1,4 Ω → IL(max) = 0,7/1,4 = {0.7/1.4*1e3:.0f} mA (sách: 500 mA).','ser',1,True)
ess(13,888,'Shunt regulator of Fig. 17–48 (series resistor R1 = 100 Ω): IL constant and VIN changes by 1 V. Change in the collector current of Q1?','Ổn áp song song Hình 17–48 (điện trở nối tiếp R1 = 100 Ω): IL không đổi và VIN đổi 1 V. Dòng cực góp Q1 thay đổi bao nhiêu?',f'ΔIC = ΔVIN/R1 = 1 V/100 Ω = {1/100*1e3:.0f} mA (book: 10 mA).',f'ΔIC = ΔVIN/R1 = 1 V/100 Ω = {1/100*1e3:.0f} mA (sách: 10 mA).','shu',2,True)
ess(15,888,'Maximum VIN in Fig. 17–48 is 25 V. Maximum output current when the output is short-circuited, and the power rating of R1 (100 Ω)?','VIN cực đại ở Hình 17–48 là 25 V. Dòng ra cực đại khi ngắn mạch ngõ ra và công suất định mức của R1 (100 Ω)?',f'IL(max) = 25 V/100 Ω = {25/100*1e3:.0f} mA; PR1 = V²/R1 = 25²/100 = {25**2/100:.2f} W (book: 250 mA, 6.25 W).',f'IL(max) = 25 V/100 Ω = {25/100*1e3:.0f} mA; PR1 = V²/R1 = 25²/100 = {25**2/100:.2f} W (sách: 250 mA, 6,25 W).','shu',2,True)
ess(17,888,'A switching regulator transistor has a switching frequency of 10 kHz with an off-time of 60 μs (Problem 16). Duty cycle, and the ideal VOUT for VIN = 12 V?','Transistor của ổn áp xung có tần số đóng ngắt 10 kHz với thời gian tắt 60 μs (Bài 16). Chu kỳ làm việc và VOUT lý tưởng khi VIN = 12 V?',f'T = 1/10 kHz = 100 μs; ton = 100 − 60 = 40 μs → duty = 40 % (book: 40 %). Ideal VOUT = duty × VIN = 0.4 × 12 = {0.4*12:.1f} V (ignoring switch and diode drops).',f'T = 1/10 kHz = 100 μs; ton = 100 − 60 = 40 μs → chu kỳ = 40 % (sách: 40 %). VOUT lý tưởng = chu kỳ × VIN = 0,4 × 12 = {0.4*12:.1f} V (bỏ qua sụt áp công tắc và điốt).','sw',2,True)
ess(20,888,'Output voltage of (a) 7806, (b) 7905.2, (c) 7818, (d) 7924.','Điện áp ra của (a) 7806, (b) 7905.2, (c) 7818, (d) 7924.','The last two digits give the voltage and the middle digit the polarity: (a) +6 V, (b) −5.2 V, (c) +18 V, (d) −24 V.','Hai chữ số cuối cho điện áp, chữ số giữa cho cực tính: (a) +6 V, (b) −5,2 V, (c) +18 V, (d) −24 V.','ic',1)
v21 = 1.25 * (1 + 10 / 1) + 50e-6 * 10e3
ess(21,888,'LM317 of Fig. 17–51: R1 = 1.0 kΩ, R2 = 10 kΩ, IADJ = 50 μA. Output voltage?','LM317 ở Hình 17–51: R1 = 1,0 kΩ, R2 = 10 kΩ, IADJ = 50 μA. Điện áp ra là bao nhiêu?',f'VOUT = VREF(1 + R2/R1) + IADJ·R2 = 1.25(1 + 10) + 50 μA × 10 kΩ = {1.25*11:.2f} + {50e-6*10e3:.2f} = {v21:.2f} V ≈ 14.3 V (book: 14.3 V).',f'VOUT = VREF(1 + R2/R1) + IADJ·R2 = 1,25(1 + 10) + 50 μA × 10 kΩ = {1.25*11:.2f} + {50e-6*10e3:.2f} = {v21:.2f} V ≈ 14,3 V (sách: 14,3 V).','ic',2,True)
ess(23,889,'With no load, how much current flows through the regulator of Figure 17–51? (Neglect IADJ.)','Khi không tải, dòng qua bộ ổn áp ở Hình 17–51 là bao nhiêu? (Bỏ qua IADJ.)',f'IR = VOUT/(R1 + R2) = {v21:.2f} V / 11 kΩ = {v21/11e3*1e3:.2f} mA ≈ 1.3 mA (book: 1.3 mA).',f'IR = VOUT/(R1 + R2) = {v21:.2f} V / 11 kΩ = {v21/11e3*1e3:.2f} mA ≈ 1,3 mA (sách: 1,3 mA).','ic',2,True)
ess(25,889,'Fig. 17–53 (7809 with external pass transistor): find Rext if the maximum internal regulator current is 250 mA.','Hình 17–53 (7809 có transistor pass ngoài): tìm Rext nếu dòng ổn áp bên trong cực đại là 250 mA.',f'Qext turns on when IREG·Rext = 0.7 V → Rext = 0.7/0.25 = {0.7/0.25:.1f} Ω (book: 2.8 Ω).',f'Qext dẫn khi IREG·Rext = 0,7 V → Rext = 0,7/0,25 = {0.7/0.25:.1f} Ω (sách: 2,8 Ω).','ic',2,True)
ess(27,889,'Add current limiting to the circuit of Figure 17–53 so the external current is limited to 2 A. Value of the limiting resistor?','Thêm giới hạn dòng cho mạch Hình 17–53 để dòng ngoài giới hạn 2 A. Điện trở giới hạn có giá trị bao nhiêu?',f'A resistor Rlimit in the emitter of Qext with a second transistor across it limits at 0.7 V: Rlimit = 0.7 V/2 A = {0.7/2:.2f} Ω (book: 0.35 Ω).',f'Điện trở Rlimit ở emitter của Qext cùng transistor thứ hai mắc ngang giới hạn ở 0,7 V: Rlimit = 0,7 V/2 A = {0.7/2:.2f} Ω (sách: 0,35 Ω).','ic',2,True)
